1	/**
2	 * @license
3	 * Copyright 2025 Google LLC
4	 * SPDX-License-Identifier: Apache-2.0
5	 */
6	
7	import type { Config } from '../../config/config.js';
8	import type { BaseLlmClient } from '../../core/baseLlmClient.js';
9	import { debugLogger } from '../../utils/debugLogger.js';
10	import { coreEvents } from '../../utils/events.js';
11	import type {
12	  RoutingContext,
13	  RoutingDecision,
14	  RoutingStrategy,
15	  TerminalStrategy,
16	} from '../routingStrategy.js';
17	
18	/**
19	 * A strategy that attempts a list of child strategies in order (Chain of Responsibility).
20	 */
21	export class CompositeStrategy implements TerminalStrategy {
22	  readonly name: string;
23	
24	  private strategies: [...RoutingStrategy[], TerminalStrategy];
25	
26	  /**
27	   * Initializes the CompositeStrategy.
28	   * @param strategies The strategies to try, in order of priority. The last strategy must be terminal.
29	   * @param name The name of this composite configuration (e.g., 'router' or 'composite').
30	   */
31	  constructor(
32	    strategies: [...RoutingStrategy[], TerminalStrategy],
33	    name: string = 'composite',
34	  ) {
35	    this.strategies = strategies;
36	    this.name = name;
37	  }
38	
39	  async route(
40	    context: RoutingContext,
41	    config: Config,
42	    baseLlmClient: BaseLlmClient,
43	  ): Promise<RoutingDecision> {
44	    const startTime = performance.now();
45	
46	    // Separate non-terminal strategies from the terminal one.
47	    // This separation allows TypeScript to understand the control flow guarantees.
48	    const nonTerminalStrategies = this.strategies.slice(
49	      0,
50	      -1,
51	    ) as RoutingStrategy[];
52	    // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
53	    const terminalStrategy = this.strategies[
54	      this.strategies.length - 1
55	    ] as TerminalStrategy;
56	
57	    // Try non-terminal strategies, allowing them to fail gracefully.
58	    for (const strategy of nonTerminalStrategies) {
59	      try {
60	        const decision = await strategy.route(context, config, baseLlmClient);
61	        if (decision) {
62	          return this.finalizeDecision(decision, startTime);
63	        }
64	      } catch (error) {
65	        debugLogger.warn(
66	          `[Routing] Strategy '${strategy.name}' failed. Continuing to next strategy. Error:`,
67	          error,
68	        );
69	      }
70	    }
71	
72	    // If no other strategy matched, execute the terminal strategy.
73	    try {
74	      const decision = await terminalStrategy.route(
75	        context,
76	        config,
77	        baseLlmClient,
78	      );
79	
80	      return this.finalizeDecision(decision, startTime);
81	    } catch (error) {
82	      coreEvents.emitFeedback(
83	        'error',
84	        `[Routing] Critical Error: Terminal strategy '${terminalStrategy.name}' failed. Routing cannot proceed. Error:`,
85	        error,
86	      );
87	      throw error;
88	    }
89	  }
90	
91	  /**
92	   * Helper function to enhance the decision metadata with composite information.
93	   */
94	  private finalizeDecision(
95	    decision: RoutingDecision,
96	    startTime: number,
97	  ): RoutingDecision {
98	    const endTime = performance.now();
99	    const compositeSource = `${this.name}/${decision.metadata.source}`;
100	
101	    // Use the child's latency if it's a meaningful (non-zero) value,
102	    // otherwise use the total time spent in the composite strategy.
103	    const latency = decision.metadata.latencyMs || endTime - startTime;
104	
105	    return {
106	      ...decision,
107	      metadata: {
108	        ...decision.metadata,
109	        source: compositeSource,
110	        latencyMs: Math.round(latency), // Round to ensure int for telemetry.
111	      },
112	    };
113	  }
114	}
